contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount to send to addToBalance and a flag to optionally call withdraw first
    function run(uint amount, bool callWithdrawFirst) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Optionally perform a prior withdraw to exercise more states (withdraw may revert if balance=0 but that's fine)
        bool withdrawReverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // Read before-values
        uint beforeRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // Call addToBalance sending 'amount' wei and record whether it reverted
        bool addReverted;
        c.addToBalance{value: amount}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            addReverted = true;
        } else {
            addReverted = false;
        }

        // Read after-values
        uint afterRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General invariant:
        // - If addToBalance succeeded: recorded balance increased by exactly amount and contract balance increased by exactly amount.
        // - If addToBalance reverted: recorded balance and contract balance are unchanged.
        assert(
            (!addReverted && afterRecorded == beforeRecorded + amount && afterContractBal == beforeContractBal + amount)
            || (addReverted && afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
        );
    }

    // Allow the contract to receive funds when c.withdrawBalance sends Ether to this contract
    receive() external payable {}
}

