// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount, bool callWithdrawFirst) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 beforeRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool addReverted;
        try c.addToBalance{value: amount}() {
            addReverted = false;
        } catch {
            addReverted = true;
        }
        uint256 afterRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue((!addReverted && afterRecorded == beforeRecorded + amount && afterContractBal == beforeContractBal + amount)
            || (addReverted && afterRecorded == beforeRecorded && afterContractBal == beforeContractBal));
    }

    function testFuzz_run(uint256 amount, bool callWithdrawFirst) public {
        _run(amount, callWithdrawFirst);
    }

    receive() external payable {}
}
